Tool response:
Tool: create_reminder_settings
Description: Configure automated email reminders for a specific event type.
The reminder will be sent X hours before the event start time, optionally including the meeting link and a custom message.
Parameters:
    {
      "type": "object",
      "properties": {
        "event_type_id": {
          "type": "integer",
          "description": "Internal ID of the event type",
          "title": "Event Type Id"
        },
        "hours_before": {
          "type": "integer",
          "title": "Hours Before",
          "description": "Number of hours before the event to send the reminder"
        },
        "include_meeting_link": {
          "type": "boolean",
          "title": "Include Meeting Link",
          "description": "Whether to include the meeting link in the reminder"
        },
        "custom_message": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Custom Message",
          "description": "Custom message to include in the reminder email"
        }
      },
      "required": [
        "event_type_id",
        "hours_before",
        "include_meeting_link"
      ]
    }

